#!/usr/bin/env node
/**
 * Stage the Safi desktop runtime into the Tauri bundle resources.
 *
 * The installed app must be self-sufficient: everything the bridge needs
 * is copied into apps/desktop/src-tauri/resources/safi, which
 * tauri.conf.json ships inside the .app / .msi / .exe. The folder is a
 * build artifact: it is gitignored and regenerated by `npm run app:stage`.
 *
 * Staged contents (no secrets, no credentials, no conversations):
 *   apps/desktop/bridge.js        hardened loopback bridge
 *   apps/desktop/host.js          desktop host adapter (single brain)
 *   apps/desktop/web/index.html   fallback page (frontendDist)
 *   ui/safi-stamp.js              Phase 3 reference stamp
 *   dist/                         compiled core (engine, translate, …)
 *   packages/safi-client/         shared client (the only brain)
 *   packages/safi-widget/         shared widget brain
 *   packages/host-contract/       consent model
 *   packages/transport-manual/    manual transport
 *   packages/verifier-calculation/
 *   packages/verifier-source/
 *   packages/adapter-provider-demo/
 *   golden/production-mascot/  the 21 production mascot masters (PNG)
 *
 *   npm run app:stage
 */
import { cpSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dest = join(root, "apps/desktop/src-tauri/resources/safi");

rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });

const files = [
  ["apps/desktop/bridge.js", "apps/desktop/bridge.js"],
  ["apps/desktop/host.js", "apps/desktop/host.js"],
  ["apps/desktop/widget.html", "apps/desktop/widget.html"],
  ["apps/desktop/web/index.html", "apps/desktop/web/index.html"],
  // Phase 3 stamp component modules, served by the bridge from /ui/*.
  // Missing projection.js was the Phase 6.1 "white square" root cause:
  // the stamp module graph failed and the page never booted.
  // The procedural mascot module is ARCHIVED, not staged: the runtime
  // renders the production masters (golden/production-mascot) only.
  ["ui/safi-stamp.js", "ui/safi-stamp.js"],
  ["ui/projection.js", "ui/projection.js"],
];

const dirs = [
  ["dist", "dist"],
  ["packages/safi-client", "packages/safi-client"],
  ["packages/safi-widget", "packages/safi-widget"],
  ["packages/host-contract", "packages/host-contract"],
  ["packages/transport-manual", "packages/transport-manual"],
  ["packages/verifier-calculation", "packages/verifier-calculation"],
  ["packages/verifier-source", "packages/verifier-source"],
  ["packages/adapter-provider-demo", "packages/adapter-provider-demo"],
  ["packages/ask-prompt-renderer", "packages/ask-prompt-renderer"],
  // Production mascot masters: the ONLY source of visible Safi pixels.
  // Staged verbatim (byte-identical, checksums verifiable in the bundle).
  ["golden/production-mascot", "golden/production-mascot"],
];

for (const [from, to] of files) {
  const src = join(root, from);
  if (!existsSync(src)) {
    console.error(`Missing ${from} — run \`npm run build\` first.`);
    process.exit(1);
  }
  cpSync(src, join(dest, to));
}

for (const [from, to] of dirs) {
  const src = join(root, from);
  if (!existsSync(src)) {
    console.error(`Missing ${from}/ — run \`npm run build\` first.`);
    process.exit(1);
  }
  cpSync(src, join(dest, to), { recursive: true });
}

// Sanity gate: credentials must never be staged.
for (const name of [".env", ".env.local", "safi-bridge-*.json"]) {
  if (name.includes("*")) continue;
  if (existsSync(join(dest, name))) {
    console.error(`Refusing to stage ${name}`);
    process.exit(1);
  }
}

console.log(`Staged Safi desktop runtime → ${dest.replace(root + "/", "")}`);
